pub fn is_non_prime(n: u64) -> bool {
    // By definition, 2 and 3 are prime, so they are not "non-prime".
    if n <= 3 {
        return false;
    }
    // Even numbers greater than 2 are non-prime.
    if n % 2 == 0 {
        return true;
    }
    // Check odd divisors from 3 up to sqrt(n).
    let mut d = 3;
    // Use d <= n/d instead of d*d <= n to avoid overflow.
    while d <= n / d {
        if n % d == 0 {
            return true;
        }
        d += 2;
    }
    // No divisor found => n is prime.
    false
}